(s) => {
  // One line per question: pass above it (or below, for a question that should be no), fail past the other, unsure between.
  const T = {
    is_certificate:    { want: true,  pass: 0.8, fail: 0.2,  reason: "not a certificate of incorporation" },
    looks_altered:     { want: false, pass: 0.6, fail: 0.8,  reason: "looks altered" },
    signature_present: { want: true,  pass: 0.7, fail: 0.25, reason: "a signature is missing" },
    date_not_future:   { want: true,  pass: 0.7, fail: 0.3,  reason: "a date is in the future" }
  };
  const raw = s["checks$answers"].answers;
  const p = {}, failed = [], unsure = [];
  for (const q of Object.keys(T)) {
    const t = T[q], v = raw[q].noul;
    p[q] = v;
    const good = t.want ? v >= t.pass : v < t.pass;
    const bad = t.want ? v < t.fail : v >= t.fail;
    if (bad) failed.push(t.reason + " (P(yes) " + v.toFixed(2) + ")");
    else if (!good) unsure.push(q + " (P(yes) " + v.toFixed(2) + ")");
  }
  return { action: failed.length ? "fail" : unsure.length ? "unsure" : "pass", failed, unsure, unsure_text: unsure.join("; "), p };
}
